-- Final business enhancements. Backup first. Apply after phase5.sql. Safe to repeat.
USE campus_repair;
SET NAMES utf8mb4;
SET @campus_new_workflow = (SELECT COUNT(*)=0 FROM information_schema.table_constraints WHERE table_schema=DATABASE() AND table_name='repair_order' AND constraint_name='chk_workflow_migration_complete');
