SET @campus_ddl = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='repair_order' AND column_name='appointment_start')=0, 'ALTER TABLE repair_order ADD COLUMN appointment_start DATETIME NULL', 'SELECT 1');
PREPARE campus_stmt FROM @campus_ddl; EXECUTE campus_stmt; DEALLOCATE PREPARE campus_stmt;
SET @campus_ddl = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='repair_order' AND column_name='appointment_end')=0, 'ALTER TABLE repair_order ADD COLUMN appointment_end DATETIME NULL', 'SELECT 1');
