SET @campus_ddl = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='repair_order' AND column_name='appointment_status')=0, 'ALTER TABLE repair_order ADD COLUMN appointment_status VARCHAR(16) NOT NULL DEFAULT \'NONE\'', 'SELECT 1');
