PREPARE campus_stmt FROM @campus_ddl; EXECUTE campus_stmt; DEALLOCATE PREPARE campus_stmt;
SET @campus_ddl = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='dispatch_record' AND column_name='round_no')=0, 'ALTER TABLE dispatch_record ADD COLUMN round_no INT NOT NULL DEFAULT 0', 'SELECT 1');
PREPARE campus_stmt FROM @campus_ddl; EXECUTE campus_stmt; DEALLOCATE PREPARE campus_stmt;
SET @campus_ddl = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='dispatch_record' AND column_name='decision')=0, 'ALTER TABLE dispatch_record ADD COLUMN decision VARCHAR(16) NOT NULL DEFAULT \'RECOMMENDED\'', 'SELECT 1');
PREPARE campus_stmt FROM @campus_ddl; EXECUTE campus_stmt; DEALLOCATE PREPARE campus_stmt;
SET @campus_ddl = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='dispatch_record' AND column_name='method')=0, 'ALTER TABLE dispatch_record ADD COLUMN method VARCHAR(16) NOT NULL DEFAULT \'SMART\'', 'SELECT 1');
PREPARE campus_stmt FROM @campus_ddl; EXECUTE campus_stmt; DEALLOCATE PREPARE campus_stmt;
SET @campus_ddl = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='dispatch_record' AND column_name='reject_reason')=0, 'ALTER TABLE dispatch_record ADD COLUMN reject_reason VARCHAR(500) NULL', 'SELECT 1');
