SET @campus_ddl = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='dispatch_record' AND column_name='response_time')=0, 'ALTER TABLE dispatch_record ADD COLUMN response_time DATETIME NULL', 'SELECT 1');
